   padding-left: 1em;
   border-left: 2px solid var(--line-strong);
   color: var(--muted);
   font-style: italic;
 }

 .prose table {
   width: 100%;
   border-collapse: collapse;
   font-size: 0.9375rem;
 }

 .prose th, .prose td {
   padding: 10px 14px;
   border-bottom: 1px solid var(--line);
   text-align: left;
   vertical-align: top;
 }

 .prose th {
   color: var(--text);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .label {
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .mono {
   font-family: var(--mono);
 }

 /* ---------------------------------------------------------------- */
 /* Layout                                                           */
 /* ---------------------------------------------------------------- */

 .shell {
   width: 100%;
   max-width: var(--w-page);
   margin-inline: auto;
   padding-inline: var(--gutter);
 }

 .shell--wide {
   max-width: var(--w-wide);
 }

 .section {
   padding-block: var(--section-y);
 }

 .section + .section {
   border-top: 1px solid var(--line);
 }

 .section__head {
   display: flex;
   flex-direction: column;
   gap: 20px;
   margin-bottom: clamp(40px, 6vw, 72px);
 }

 .grid {
   display: grid;
   gap: 20px;
 }

 .grid--2 { grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); }
-.grid--3 { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }
+.grid--3 { grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); }
 .grid--4 { grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }

 .stack {
   display: flex;
   flex-direction: column;
   gap: 16px;
 }

 .cluster {
   display: flex;
   flex-wrap: wrap;
   gap: 10px;
   align-items: center;
 }

 /* ---------------------------------------------------------------- */
 /* Header & footer                                                  */
 /* ---------------------------------------------------------------- */

 .site-header {
   position: sticky;
   top: 0;
   z-index: 50;
   border-bottom: 1px solid var(--line);
   background: color-mix(in srgb, var(--bg) 72%, transparent);
   backdrop-filter: blur(16px) saturate(180%);
   -webkit-backdrop-filter: blur(16px) saturate(180%);
 }

 .site-header__inner {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 20px;
   width: 100%;
   max-width: var(--w-page);
   margin-inline: auto;
   padding: 14px var(--gutter);
 }

 .brand {
   display: inline-flex;
   align-items: center;
   gap: 10px;
   color: var(--text);
 }

 .brand:hover { color: var(--text); }

 .brand__name {
   font-size: 0.9375rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .site-nav {
   display: flex;
   gap: 24px;
   font-size: 0.875rem;
   color: var(--muted);
 }

 .site-nav a:hover {
   color: var(--text);
 }

 .site-footer {
   border-top: 1px solid var(--line);
   padding-block: clamp(48px, 7vw, 88px);
   color: var(--faint);
   font-size: 0.875rem;
 }

 .site-footer__top {
   display: flex;
   flex-wrap: wrap;
   align-items: baseline;
   justify-content: space-between;
   gap: 12px 24px;
   margin-bottom: 28px;
 }

 .site-footer__brand {
   display: inline-flex;
   align-items: center;
   gap: 10px;
   color: var(--text);
 }

 .site-footer__tagline {
   color: var(--muted);
 }

 .site-footer__nav {
   display: flex;
   flex-wrap: wrap;
   gap: 8px 24px;
   margin-bottom: 28px;
 }

 .site-footer__nav a {
   color: var(--muted);
 }

 .site-footer__nav a:hover {
   color: var(--text);
 }

 .site-footer__legal {
   color: var(--faint);
 }

 .site-footer__note {
   margin-top: 6px;
   color: var(--faint);
 }

 /* ---------------------------------------------------------------- */
 /* Buttons, pills, cards                                            */
 /* ---------------------------------------------------------------- */

 .btn {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   gap: 8px;
   padding: 13px 24px;
   border: 1px solid transparent;
   border-radius: var(--r-pill);
   font-size: 0.9375rem;
   font-weight: 600;
   letter-spacing: -0.01em;
   transition:
     transform 0.15s var(--ease-tactile),
     background-color 0.15s var(--ease-tactile),
     border-color 0.15s var(--ease-tactile),
     opacity 0.15s var(--ease-tactile);
 }

 .btn--primary {
   background: var(--accent);
   color: var(--accent-ink);
 }

 .btn--primary:hover {
   color: var(--accent-ink);
   transform: translateY(-1px);
   opacity: 0.92;
 }

 .btn--ghost {
   border-color: var(--line-strong);
   background: var(--surface);
   color: var(--text);
 }

 .btn--ghost:hover {
   color: var(--text);
   transform: translateY(-1px);
   background: var(--surface-hover);
 }

 .btn--sm {
   padding: 9px 18px;
   font-size: 0.875rem;
 }

 .btn:active {
   transform: scale(0.98);
 }

 .pill {
   display: inline-flex;
   align-items: center;
   gap: 6px;
   padding: 3px 10px;
   border: 1px solid var(--line-strong);
   border-radius: var(--r-pill);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.06em;
   text-transform: uppercase;
   color: var(--muted);
   white-space: nowrap;
 }

 .pill--accent {
   border-color: color-mix(in srgb, var(--accent) 34%, transparent);
   background: color-mix(in srgb, var(--accent) 12%, transparent);
   color: var(--accent);
 }

 .pill--positive {
   border-color: color-mix(in srgb, var(--green) 28%, transparent);
   background: color-mix(in srgb, var(--green) 10%, transparent);
   color: var(--green);
 }

 .pill--warning {
   border-color: color-mix(in srgb, var(--amber) 30%, transparent);
   background: color-mix(in srgb, var(--amber) 10%, transparent);
   color: var(--amber);
 }

 .card {
   padding: 24px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
   transition:
     transform 0.2s var(--ease-apple-out),
     border-color 0.2s var(--ease-apple-out),
     background-color 0.2s var(--ease-apple-out);
 }

 .card:hover {
   transform: translateY(-2px);
   border-color: var(--line-strong);
   background: var(--surface-hover);
 }

 .card__title {
   font-size: 1.0625rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .card__body {
   margin-top: 10px;
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 .glass {
   border: 1px solid var(--line-strong);
   border-radius: var(--r-lg);
   background: var(--glass);
   backdrop-filter: var(--glass-blur);
   -webkit-backdrop-filter: var(--glass-blur);
   box-shadow: var(--hairline), 0 40px 120px -20px rgba(0, 0, 0, 0.85);
 }

 /* ---------------------------------------------------------------- */
 /* Hero                                                             */
 /* ---------------------------------------------------------------- */

 .hero {
   display: flex;
   align-items: center;
   min-height: calc(100svh - 68px);
   padding-block: clamp(72px, 11vw, 140px);
   text-align: center;
 }

 .hero__inner {
   display: flex;
   flex-direction: column;
   align-items: center;
   gap: 24px;
 }

 .hero__title {
-  max-width: 16ch;
+  max-width: 20ch;
+  text-wrap: balance;
   font-size: clamp(2.75rem, 7.5vw, 6rem);
   font-weight: 600;
   letter-spacing: -0.04em;
   line-height: 0.98;
 }

 .hero__sub {
   max-width: 46ch;
   color: var(--muted);
   font-size: clamp(1.0625rem, 1.6vw, 1.375rem);
   line-height: 1.5;
 }

 .hero__actions {
   display: flex;
   flex-wrap: wrap;
   justify-content: center;
   gap: 12px;
   margin-top: 8px;
 }

 .hero__cue {
   display: inline-flex;
   align-items: center;
   gap: 8px;
   margin-top: 12px;
   color: var(--faint);
   font-size: 0.8125rem;
 }

 .hero__cue span {
   display: block;
   width: 1px;
   height: 22px;
   background: linear-gradient(to bottom, var(--line-strong), transparent);
 }

 /* ---------------------------------------------------------------- */
 /* Problem                                                          */
 /* ---------------------------------------------------------------- */

 .beats {
   display: grid;
   gap: 20px;
   grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
 }

 .beat {
   display: flex;
   flex-direction: column;
   gap: 12px;
   padding: 26px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
 }

 .beat__quote {
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
   line-height: 1.35;
 }

 .beat__support {
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 .closer {
   margin-top: 40px;
   max-width: 34ch;
   font-size: clamp(1.375rem, 2.4vw, 2rem);
   font-weight: 600;
   letter-spacing: -0.025em;
   line-height: 1.2;
   color: var(--text);
 }

 /* ---------------------------------------------------------------- */
 /* Insight — the formula                                            */
 /* ---------------------------------------------------------------- */

 .insight {
   display: grid;
   gap: clamp(40px, 6vw, 72px);
   grid-template-columns: minmax(0, 1fr);
   align-items: start;
 }

 @media (min-width: 960px) {
   .insight {
     grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
   }
 }

 .formula {
   display: flex;
   flex-wrap: wrap;
   align-items: baseline;
   gap: 10px;
+  overflow-x: auto;
   padding: 22px 24px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--bg-sunken);
   font-family: var(--mono);
   font-size: clamp(0.9375rem, 1.6vw, 1.125rem);
   line-height: 1.5;
 }

 .formula__label {
   color: var(--muted);
 }

 .formula__expr {
   color: var(--text);
+  white-space: nowrap;
 }

 .formula__gap {
   color: var(--accent);
 }

 .statline {
   display: flex;
   flex-wrap: wrap;
   align-items: baseline;
   gap: 8px 12px;
   margin-top: 20px;
   font-size: 0.9375rem;
 }

 .statline__value {
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .statline__source {
   color: var(--faint);
 }

 /* The importance/satisfaction gap, drawn honestly. */
 .gap {
   display: flex;
   flex-direction: column;
   gap: 14px;
   padding: 24px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
 }

 .gap__row {
   display: grid;
   grid-template-columns: 96px 1fr 40px;
   align-items: center;
   gap: 14px;
   font-size: 0.8125rem;
   color: var(--muted);
 }

 .gap__track {
+  display: block;
   height: 8px;
   border-radius: var(--r-pill);
   background: var(--surface-hover);
   overflow: hidden;
 }

 .gap__fill {
+  display: block;
   height: 100%;
   border-radius: var(--r-pill);
   background: var(--accent-strong);
 }

 .gap__fill--satisfaction {
   background: color-mix(in srgb, var(--muted) 55%, transparent);
 }

 .gap__value {
   font-family: var(--mono);
   font-size: 0.8125rem;
   text-align: right;
   color: var(--text);
 }

 .gap__note {
   color: var(--faint);
   font-size: 0.8125rem;
   line-height: 1.5;
 }

 /* ---------------------------------------------------------------- */
 /* The demo — the Living Studio, running its script                  */
 /* ---------------------------------------------------------------- */

 .demo {
   display: flex;
   flex-direction: column;
   gap: 18px;
 }

 .demo__notice {
   display: flex;
   flex-wrap: wrap;
   align-items: center;
   gap: 10px 16px;
 }

 .demo__label {
   display: inline-flex;
   align-items: center;
   padding: 4px 12px;
   border: 1px solid color-mix(in srgb, var(--amber) 32%, transparent);
   border-radius: var(--r-pill);
   background: color-mix(in srgb, var(--amber) 10%, transparent);
   color: var(--amber);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   text-transform: uppercase;
   white-space: nowrap;
 }

 .demo__disclaimer {
   color: var(--faint);
   font-size: 0.875rem;
   line-height: 1.5;
 }

 .demo__disclaimer a {
   color: var(--muted);
   text-decoration: underline;
   text-underline-offset: 3px;
 }

 .demo__disclaimer a:hover {
   color: var(--text);
 }

 .demo__frame {
   overflow: hidden;
   border-radius: var(--r-lg);
   background: var(--bg-raised);
 }

 .demo__bar {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 12px;
   height: 46px;
   padding: 0 16px;
   border-bottom: 1px solid var(--line);
 }

 .demo__brand {
   display: inline-flex;
   align-items: center;
   gap: 9px;
   font-size: 0.8125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .demo__health {
   display: inline-flex;
   align-items: center;
   gap: 7px;
   padding: 4px 11px;
   border: 1px solid var(--line);
   border-radius: var(--r-pill);
   color: var(--faint);
   font-size: 0.6875rem;
 }

 .demo__dot {
   width: 6px;
   height: 6px;
   border-radius: 50%;
   background: var(--green);
   box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 14%, transparent);
 }

 .demo__transcript,
 .demo__live {
   padding: 22px;
 }

 .demo__thread {
   min-height: 280px;
 }

 .demo__exchange + .demo__exchange {
   margin-top: 22px;
 }

 .demo__msg {
   display: flex;
   gap: 12px;
 }

 .demo__msg + .demo__msg {
   margin-top: 18px;
 }

 .demo__msg--user {
   justify-content: flex-end;
 }

 .demo__msg--assistant {
   align-items: flex-start;
   transition:
     opacity 0.5s var(--ease-apple-out),
     transform 0.5s var(--ease-apple-out);
 }

 .demo__msg--assistant.is-pending {
   opacity: 0;
   transform: translateY(8px);
 }

 .demo__bubble {
   max-width: 78%;
   padding: 10px 14px;
   border: 1px solid var(--line);
   border-radius: 18px 18px 6px 18px;
   background: var(--surface-hover);
   font-size: 0.9375rem;
   line-height: 1.55;
   white-space: pre-wrap;
   overflow-wrap: anywhere;
 }

 .demo__msg-body {
   flex: 1;
   min-width: 0;
   display: flex;
   flex-direction: column;
   gap: 14px;
 }

 .demo__reply {
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 .demo__avatar {
   display: grid;
   place-items: center;
   width: 26px;
   height: 26px;
   flex: none;
   margin-top: 2px;
   border-radius: 8px;
   background: linear-gradient(140deg, var(--accent-strong), var(--accent));
   color: var(--bg);
 }

 .demo__typing {
   display: flex;
   align-items: center;
   gap: 9px;
   margin-top: 18px;
 }

 .typing__dots {
   display: inline-flex;
   gap: 3px;
 }

 .typing__dots i {
   width: 5px;
   height: 5px;
   border-radius: 50%;
   background: var(--faint);
   animation: caret-blink 1.2s infinite ease-in-out;
 }

 .typing__dots i:nth-child(2) { animation-delay: 0.15s; }
 .typing__dots i:nth-child(3) { animation-delay: 0.3s; }

 .demo__composer {
   display: flex;
   align-items: flex-end;
   gap: 10px;
   margin-top: 18px;
   padding: 8px 9px 8px 16px;
   border: 1px solid var(--line);
   border-radius: 22px;
   background: var(--surface);
   transition: border-color 0.16s var(--ease-tactile);
 }

 .demo__composer:focus-within {
   border-color: color-mix(in srgb, var(--accent) 42%, transparent);
 }

 .demo__input {
   flex: 1;
   min-width: 0;
   max-height: 140px;
   padding: 8px 0;
   border: 0;
   background: transparent;
   color: var(--text);
   font-size: 0.9375rem;
   line-height: 1.5;
   resize: none;
   outline: none;
 }

 .demo__input::placeholder {
   color: var(--faint);
 }

 .demo__send {
   display: grid;
   place-items: center;
   width: 34px;
   height: 34px;
   flex: none;
   border-radius: 50%;
   background: var(--text);
   color: var(--bg);
   transition:
     transform 0.15s var(--ease-tactile),
     opacity 0.15s var(--ease-tactile);
 }

 .demo__send:hover {
   transform: translateY(-1px);
 }

 .demo__chips {
   display: flex;
   flex-wrap: wrap;
   gap: 7px;
   margin-top: 14px;
 }

 .demo__chip {
   display: inline-flex;
   align-items: center;
   padding: 6px 12px;
   border: 1px solid var(--line);
   border-radius: var(--r-pill);
   background: var(--surface);
   color: var(--muted);
   font-size: 0.8125rem;
   text-align: left;
   transition:
     background-color 0.15s var(--ease-tactile),
     border-color 0.15s var(--ease-tactile),
     color 0.15s var(--ease-tactile),
     transform 0.15s var(--ease-tactile);
 }

 .demo__chip:hover {
   transform: translateY(-1px);
   border-color: var(--line-strong);
   background: var(--surface-hover);
   color: var(--text);
 }

 /* ---------------------------------------------------------------- */
 /* Run it                                                           */
 /* ---------------------------------------------------------------- */

 .run {
   display: flex;
   flex-direction: column;
   gap: 32px;
 }

 .run__grid {
   display: grid;
   gap: 28px;
   grid-template-columns: minmax(0, 1fr);
 }

 @media (min-width: 960px) {
   .run__grid {
     grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
   }
 }

 .run__label {
   margin-bottom: 12px;
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .run__note {
   color: var(--muted);
   font-size: 0.9375rem;
 }

 .copy-btn--inline {
   position: static;
   flex: none;
   padding: 3px 9px;
   font-size: 0.6875rem;
   opacity: 1;
 }

 .section__more {
   margin-top: 32px;
 }

 .status-note--muted {
   margin-top: 10px;
   font-weight: 400;
   color: var(--muted);
 }

 /* ---------------------------------------------------------------- */
 /* Surfaces — the six catalog cards                                  */
 /* ---------------------------------------------------------------- */

 .surface {
   display: flex;
   flex-direction: column;
   gap: 14px;
   padding: 22px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--bg-raised);
   box-shadow: var(--hairline);
 }

 .surface__head {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 12px;
 }

 .surface__id {
   font-family: var(--mono);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   color: var(--accent);
 }

 .surface__statement {
   font-size: 0.9375rem;
   font-weight: 500;
   line-height: 1.5;
 }

 .surface__meta {
   display: flex;
   flex-wrap: wrap;
   gap: 6px;
 }

 .surface__scores {
   display: flex;
+  flex-wrap: wrap;
   align-items: baseline;
-  gap: 10px;
+  gap: 4px 10px;
   font-family: var(--mono);
   font-size: 0.8125rem;
   color: var(--muted);
 }

 .surface__opportunity {
   font-size: 1.375rem;
   font-weight: 600;
   letter-spacing: -0.02em;
   color: var(--text);
 }

 .meter {
   display: flex;
   flex-direction: column;
   gap: 6px;
 }

 .meter__head {
   display: flex;
   justify-content: space-between;
   font-size: 0.6875rem;
   letter-spacing: 0.07em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .meter__track {
+  display: block;
   height: 6px;
   border-radius: var(--r-pill);
   background: var(--surface-hover);
   overflow: hidden;
 }

 .meter__fill {
+  display: block;
   height: 100%;
   border-radius: var(--r-pill);
   background: var(--accent);
 }

 .meter__fill--positive { background: var(--green); }
 .meter__fill--warning { background: var(--amber); }

 .surface-card {
+  container-type: inline-size;
   display: flex;
   flex-direction: column;
   gap: 14px;
   padding: 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
   transition:
     transform 0.2s var(--ease-apple-out),
     border-color 0.2s var(--ease-apple-out);
 }

 .surface-card:hover {
   transform: translateY(-2px);
   border-color: var(--line-strong);
 }

 .surface-card__head {
   display: flex;
   align-items: baseline;
   justify-content: space-between;
   gap: 12px;
 }

 .surface-card__title {
   font-size: 1rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .surface-card__type {
   font-family: var(--mono);
   font-size: 0.6875rem;
   color: var(--faint);
 }

 .surface-card__blurb {
+  margin-top: auto;
   color: var(--muted);
   font-size: 0.875rem;
   line-height: 1.55;
 }

 .surface-card .surface {
   background: var(--bg-raised);
 }

 .surface__row + .surface__row {
   padding-top: 12px;
   border-top: 1px solid var(--line);
 }

 .connector-group__title {
   margin-bottom: 16px;
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.12em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .jobmap {
   display: flex;
   flex-direction: column;
   gap: 6px;
   margin: 0;
   padding: 0;
   list-style: none;
 }

 .jobmap__step {
   display: flex;
   align-items: baseline;
   gap: 10px;
   padding: 9px 12px;
   border-left: 2px solid color-mix(in srgb, var(--accent) 50%, transparent);
   border-radius: 0 var(--r-sm) var(--r-sm) 0;
   background: var(--surface);
   font-size: 0.875rem;
 }

 .jobmap__index {
   font-family: var(--mono);
   font-size: 0.6875rem;
   color: var(--accent);
 }

 .compare {
   display: grid;
   gap: 8px;
   grid-template-columns: 1fr 1fr;
 }

+@container (max-width: 460px) {
+  .compare {
+    grid-template-columns: 1fr;
+  }
+}
+
 .compare__col {
   padding: 12px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   font-size: 0.8125rem;
   line-height: 1.5;
 }

 .compare__col--after {
   border-color: color-mix(in srgb, var(--green) 22%, transparent);
   background: color-mix(in srgb, var(--green) 6%, transparent);
 }

 .compare__col--before {
   border-color: color-mix(in srgb, var(--red) 20%, transparent);
   background: color-mix(in srgb, var(--red) 6%, transparent);
 }

 .compare__label {
   display: block;
   margin-bottom: 6px;
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .evidence {
   padding: 12px 14px;
   border-left: 2px solid color-mix(in srgb, var(--accent) 50%, transparent);
   border-radius: 0 var(--r-sm) var(--r-sm) 0;
   background: var(--surface);
 }

 .evidence__quote {
   color: var(--text);
   font-size: 0.875rem;
   font-style: italic;
   line-height: 1.55;
 }

 .evidence__meta {
   display: block;
   margin-top: 8px;
   color: var(--faint);
   font-size: 0.6875rem;
 }

 /* ---------------------------------------------------------------- */
 /* Steps                                                            */
 /* ---------------------------------------------------------------- */

 .steps {
   display: grid;
   gap: 20px;
   grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
   counter-reset: step;
 }

 .step {
   position: relative;
   display: flex;
   flex-direction: column;
   gap: 12px;
   padding: 26px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
   counter-increment: step;
 }

 .step::before {
   content: counter(step, decimal-leading-zero);
   font-family: var(--mono);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   color: var(--accent);
 }

 .step__title {
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .step__body {
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 /* ---------------------------------------------------------------- */
 /* Connectors                                                       */
 /* ---------------------------------------------------------------- */

 .connector-group + .connector-group {
   margin-top: 36px;
 }

 .connector-list {
   display: grid;
   gap: 12px;
   grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
 }

 .connector {
   display: flex;
   flex-direction: column;
   gap: 8px;
   padding: 18px 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--surface);
   transition:
     transform 0.18s var(--ease-apple-out),
     border-color 0.18s var(--ease-apple-out);
 }

 .connector:hover {
   transform: translateY(-2px);
   border-color: var(--line-strong);
 }

 .connector__head {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 10px;
 }

 .connector__name {
   font-size: 0.9375rem;
   font-weight: 600;
 }

 .connector__summary {
   color: var(--muted);
   font-size: 0.8125rem;
   line-height: 1.55;
 }

 .connector__env {
   font-family: var(--mono);
   font-size: 0.6875rem;
   color: var(--faint);
 }

 /* ---------------------------------------------------------------- */
 /* Code                                                             */
 /* ---------------------------------------------------------------- */

 .codeblock {
   position: relative;
   margin: 0;
   padding: 20px 22px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--bg-sunken);
   overflow-x: auto;
   font-family: var(--mono);
   font-size: 0.875rem;
   line-height: 1.65;
   color: var(--text);
   tab-size: 2;
 }

 .codeblock code {
   font-family: var(--mono);
 }

 .copy-btn {
   position: absolute;
   top: 10px;
   right: 10px;
   padding: 5px 12px;
   border: 1px solid var(--line-strong);
   border-radius: var(--r-pill);
   background: var(--bg-raised);
   color: var(--muted);
   font-family: var(--font);
   font-size: 0.75rem;
   font-weight: 600;
   opacity: 0;
   transition:
     opacity 0.15s var(--ease-tactile),
     color 0.15s var(--ease-tactile),
     border-color 0.15s var(--ease-tactile);
 }

 .codeblock:hover .copy-btn,
 .copy-btn:focus-visible {
   opacity: 1;
 }

 .copy-btn:hover {
   color: var(--text);
   border-color: var(--line-strong);
 }

 /* Syntax highlighting, server-rendered by Pygments. */
 .highlight {
   margin: 0;
   padding: 20px 22px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--bg-sunken);
   overflow-x: auto;
   font-family: var(--mono);
   font-size: 0.875rem;
   line-height: 1.65;
 }

 .highlight pre {
   margin: 0;
   font-family: var(--mono);
 }

 .highlight code {
   font-family: var(--mono);
 }

 /* ---------------------------------------------------------------- */
 /* Tabs                                                             */
 /* ---------------------------------------------------------------- */

 .tabs__list {
   display: inline-flex;
   gap: 4px;
   padding: 4px;
   border: 1px solid var(--line);
   border-radius: var(--r-pill);
   background: var(--surface);
 }

 .tabs__tab {
   padding: 8px 18px;
   border-radius: var(--r-pill);
   font-size: 0.875rem;
   font-weight: 500;
   color: var(--muted);
   transition:
     background-color 0.15s var(--ease-tactile),
     color 0.15s var(--ease-tactile);
 }

 .tabs__tab[aria-selected="true"] {
   background: var(--surface-hover);
   color: var(--text);
 }

 .tabs__panel {
   margin-top: 20px;
 }

 .tabs__panel[hidden] {
   display: none;
 }

 /* ---------------------------------------------------------------- */
 /* Endpoints                                                        */
 /* ---------------------------------------------------------------- */

 .endpoints {
   display: flex;
   flex-direction: column;
   gap: 0;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   overflow: hidden;
 }

 .endpoint {
   display: grid;
   gap: 4px 20px;
   grid-template-columns: minmax(0, 1fr);
   padding: 18px 22px;
   background: var(--surface);
 }

 .endpoint + .endpoint {
   border-top: 1px solid var(--line);
 }

 @media (min-width: 760px) {
   .endpoint {
     grid-template-columns: 200px minmax(0, 1fr);
     align-items: center;
   }
 }

 .endpoint__name {
   font-size: 0.875rem;
   font-weight: 600;
 }

 .endpoint__url {
   display: flex;
   align-items: center;
   gap: 10px;
   font-family: var(--mono);
   font-size: 0.8125rem;
   color: var(--muted);
   overflow-wrap: anywhere;
 }

 .endpoint__note {
   grid-column: 1 / -1;
   color: var(--faint);
   font-size: 0.8125rem;
   line-height: 1.5;
 }

 /* ---------------------------------------------------------------- */
 /* Tools preview                                                    */
 /* ---------------------------------------------------------------- */

 .tool {
   display: flex;
   flex-direction: column;
   gap: 8px;
   padding: 18px 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--surface);
 }

 .tool__name {
   font-family: var(--mono);
   font-size: 0.875rem;
   font-weight: 600;
   color: var(--accent);
 }

 .tool__purpose {
   color: var(--muted);
   font-size: 0.875rem;
   line-height: 1.55;
 }

 .tool__sig {
   font-family: var(--mono);
   font-size: 0.75rem;
   color: var(--faint);
   overflow-wrap: anywhere;
 }

 /* ---------------------------------------------------------------- */
 /* Status                                                           */
 /* ---------------------------------------------------------------- */

 .status-grid {
   display: grid;
   gap: 20px;
   grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
 }

 .status-list {
   display: flex;
   flex-direction: column;
   gap: 12px;
   margin: 0;
   padding: 0;
   list-style: none;
 }

 .status-list li {
   display: flex;
   align-items: baseline;
   gap: 10px;
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.55;
 }

 .status-list li::before {
   content: "";
   flex: none;
   width: 5px;
   height: 5px;
   margin-top: 9px;
   border-radius: 50%;
   background: var(--accent);
 }

 .status-note {
   margin-top: 40px;
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 /* ---------------------------------------------------------------- */
 /* Motion                                                           */
 /* ---------------------------------------------------------------- */

 @keyframes hero-in {
   from {
     opacity: 0;
     transform: translateY(10px);
     filter: blur(4px);
   }
   to {
     opacity: 1;
     transform: none;
     filter: blur(0);
   }
 }

 @keyframes reveal-up {
   from {
     opacity: 0;
     transform: translateY(24px);
   }
   to {
     opacity: 1;
     transform: none;
   }
 }

 @keyframes surface-in {
   from {
     opacity: 0;
     transform: translateY(10px) scale(0.985);
   }
   to {
     opacity: 1;
     transform: none;
   }
 }

 @keyframes caret-blink {
   0%, 45% { opacity: 1; }
   46%, 100% { opacity: 0; }
 }

 .hero__eyebrow { animation: hero-in 0.7s var(--ease-apple-out) both; }
 .hero__title    { animation: hero-in 0.7s var(--ease-apple-out) 0.09s both; }
 .hero__sub      { animation: hero-in 0.7s var(--ease-apple-out) 0.18s both; }
 .hero__actions  { animation: hero-in 0.7s var(--ease-apple-out) 0.27s both; }
 .hero__cue      { animation: hero-in 0.7s var(--ease-apple-out) 0.36s both; }

 /* Reveal-on-scroll. Content is visible by default; the observer opts it
    into the hidden state only after it loads, so no-JS readers never lose
    anything. */
 .js-reveal [data-reveal] {
   opacity: 0;
   transform: translateY(24px);
   transition:
     opacity 0.8s var(--ease-apple-out),
     transform 0.8s var(--ease-apple-out);
 }

 .js-reveal [data-reveal].is-visible {
   opacity: 1;
   transform: none;
 }

 @media (prefers-reduced-motion: reduce) {
   html {
     scroll-behavior: auto;
   }

   *,
   *::before,
   *::after {
     animation-duration: 0.001ms !important;
     animation-iteration-count: 1 !important;
     transition-duration: 0.001ms !important;
     scroll-behavior: auto !important;
   }

   .js-reveal [data-reveal] {
     opacity: 1;
     transform: none;
   }
 }

 /* ---------------------------------------------------------------- */
 /* Responsive                                                       */
 /* ---------------------------------------------------------------- */

 @media (max-width: 860px) {
   .site-nav {
     display: none;
   }
 }

 @media (max-width: 640px) {
   .compare {
     grid-template-columns: 1fr;
   }

   .gap__row {
     grid-template-columns: 78px 1fr 34px;
     gap: 10px;
   }
 }

