      <path d="m5 13 4.5 4.5L19 7" />
    </Icon>
  );
}

export function SparkIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="M12 4l1.6 4.6L18 10l-4.4 1.4L12 16l-1.6-4.6L6 10l4.4-1.4z" />
    </Icon>
  );
}

export function ArrowLeftIcon(props: IconProps) {
  return (
    <svg
      width={props.size ?? 18}
